def mutual_info(channel, prior):
    num_states = len(prior)

    # Calculate H(X) - entropy of input random variable
    hx = 0
    for i in range(num_states):
        if prior[i] != 0:
            hx += prior[i] * np.log2(prior[i])

    # Calculate H(Y|X) - conditional entropy of output given input
    hxy = 0
    for j in range(len(channel[0])):
        total_p_x_y = 0
        for i in range(num_states):
            total_p_x_y += channel[i][j] * prior[i]

        if total_p_x_y != 0:
            for i in range(num_states):
                hxy -= channel[i][j] * prior[i] * np.log2(channel[i][j] / (total_p_x_y))

    # Calculate H(Y) - entropy of output random variable
    hy = 0
    total_p_y = 0
    for j in range(len(channel[0])):
        for i in range(num_states):
