class Jastrow:
    def __init__(self, beta=1):
        self.beta = beta

    def get_r_vec(self, configs):
        r1 = configs[:, 0]
        r2 = configs[:, 1]
        return r1 - r2

    def get_r_ee(self, configs):
        r12 = self.get_r_vec(configs)
        return np.linalg.norm(r12, axis=1)

    def value(self, configs):
        r_ee = self.get_r_ee(configs)
        return np.exp(self.beta * r_ee)

    def gradient(self, configs):
        r12 = self.get_r_vec(configs)
        r_ee = self.get_r_ee(configs)
        grad_r1 = -self.beta / r_ee[:, None] * (r12[:, 0], r12[:, 1])
        grad_r2 = self.beta / r_ee[:, None] * (r12[:, 0], r12[:, 1])
        return np.concatenate((grad_r1, grad_r2), axis=1)

    def laplacian(self, configs):
        r_ee = self.get_r_ee(configs)
        laplacian_r1 = -self.beta / r_ee + self.beta**2
        laplacian_r2 = -self.beta / r_ee + self.beta**2
        return np.array([laplacian_r1, laplacian_r2]).T
