                self.wf2.value(configs) * grad_wf1) / self.value(configs)

    def laplacian(self, configs):
        lap_wf1 = self.wf1.laplacian(configs)
        lap_wf2 = self.wf2.laplacian(configs)
        return (self.wf1.value(configs) * lap_wf2 + 
                2 * self.wf1.gradient(configs).T @ self.wf2.gradient(configs) + 
                self.wf2.value(configs) * lap_wf1) / self.value(configs)

    def kinetic(self, configs):
        value = self.value(configs)
        laplacian = self.laplacian(configs)
        return (np.einsum('ik,ik->i', value, laplacian)) / value
