class Slater:
    def __init__(self, alpha):
        self.alpha = alpha

    def value(self, configs):
        nconf, nelec, ndim = configs.shape
        val = np.exp(-self.alpha * np.linalg.norm(configs[:, 0], axis=1)) * \
              np.exp(-self.alpha * np.linalg.norm(configs[:, 1], axis=1))
        return val.reshape((nconf,))

    def gradient(self, configs):
        nconf, nelec, ndim = configs.shape
        grad = -self.alpha * (configs[:, 0] / np.linalg.norm(configs[:, 0], axis=1)[:, None]) + \
               -self.alpha * (configs[:, 1] / np.linalg.norm(configs[:, 1], axis=1)[:, None])
        return grad

    def laplacian(self, configs):
        nconf, nelec, ndim = configs.shape
        lap = (-2 * self.alpha / np.linalg.norm(configs[:, 0], axis=1)) + \
              (self.alpha ** 2) + \
              (-2 * self.alpha / np.linalg.norm(configs[:, 1], axis=1)) + \
              (self.alpha ** 2)
        return lap.reshape((nconf, nelec))

    def kinetic(self, configs):
        nconf, nelec, ndim = configs.shape
        kin = -0.5 * ((configs[:, 0] / np.linalg.norm(configs[:, 0], axis=1)[:, None]) ** 2 + \
                       (configs[:, 1] / np.linalg.norm(configs[:, 1], axis=1)[:, None]) ** 2)
        return kin.reshape((nconf,))
